class SingleFlight:
    def __init__(self):
        self._inflight = {}

    def submit(self, key, fn, *args, **kwargs):
        if key not in self._inflight:
            self._inflight[key] = {
                'fn': lambda: fn(*args, **kwargs),
                'callers': 0,
                'resolved': False,
                'val': None,
                'err': None
            }
        entry = self._inflight[key]
        entry['callers'] += 1
        return lambda: self._resolve(key, entry)

    def _resolve(self, key, entry):
        if not entry['resolved']:
            try:
                entry['val'] = entry['fn']()
            except Exception as e:
                entry['err'] = e
            finally:
                entry['resolved'] = True
                self._inflight.pop(key, None)
        if entry['err'] is not None:
            raise entry['err']
        return entry['val'], entry['callers'] > 1

    def do(self, key, fn, *args, **kwargs):
        return self.submit(key, fn, *args, **kwargs)()

    def forget(self, key):
        self._inflight.pop(key, None)

    def in_flight_count(self):
        return len(self._inflight)
